<script module lang="ts">
/**
 * RichTextContent.Inlines: a paragraph’s or a heading’s drawn inlines, each as the element or member of its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { getContext } from 'svelte'

import {
  Render,
  attributes,
  joinSlot,
  richTextPositionAttrs,
  type RichTextDrawnInline,
  type RichTextEntity,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import Code from './Code.svelte'
import Link from '../controls/Link.svelte'
import RichTextContentInlines from './RichTextContentInlines.svelte'

export interface RichTextContentInlinesProps {
  inlines: RichTextDrawnInline[]
}
</script>

<script lang="ts">
let { inlines }: RichTextContentInlinesProps = $props()
const joined = joinSlot(undefined, () => ({}))
const owner: Record<string, any> = getContext('polymorph:RichTextContent') ?? {}
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#each inlines as node, index (index)
    }{#if node.kind === 'text'
      }{node.text
    }{:else if node.kind === 'strong'
      }<strong><RichTextContentInlines inlines={node.children} /></strong
    >{:else if node.kind === 'em'
      }<em><RichTextContentInlines inlines={node.children} /></em
    >{:else if node.kind === 's'
      }<s><RichTextContentInlines inlines={node.children} /></s
    >{:else if node.kind === 'mark'
      }<mark
        class={[styles.annotation, owner.pressable ? styles.pressable : undefined]}
        data-annotation-id={node.id}
        data-active={(node.active) ? '' : undefined}
        role={(node.stop) ? 'button' : undefined}
        tabindex={((node.stop) ? '0' : undefined) as never}
        aria-current={(node.stop && node.active) ? 'true' : undefined}
        ><RichTextContentInlines inlines={node.children}
      /></mark
    >{:else if node.kind === 'code'
      }<Code>{node.text}</Code
    >{:else if node.kind === 'ownCode'
      }<code class={styles.code}><RichTextContentInlines inlines={node.children} /></code
    >{:else if node.kind === 'link' && owner.routes
      }<Link
        href={node.href}
        external={node.external}
        onNavigate={(event) => { (owner.navigate as (href: string) => void)(event) }}
        >{node.text
      }</Link
    >{:else if node.kind === 'link'
      }<Link href={node.href} external={node.external}>{node.text}</Link
    >{:else if node.kind === 'break'
      }<br {...attributes(richTextPositionAttrs(node.at, true))}
    />{:else if node.kind === 'entity' && node.app
      }<Render node={(owner.entityNode as (entity: RichTextEntity) => never)(node.entity)}
    />{:else if node.kind === 'entity'
      }<span
        class={styles.entity}
        data-entity-kind={node.entity.kind}
        data-entity-id={node.entity.id}
        >{node.entity.label
      }</span
    >{:else if node.kind === 'piece'
      }<span {...attributes(richTextPositionAttrs(node.at, node.atom, false))}
        ><RichTextContentInlines inlines={node.children}
      /></span
    >{/if
  }{/each
}{/if
}{@render joined.end?.()}
